import { useState, useEffect, useCallback } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:5000/api';

const useMessages = () => {
  const [conversations, setConversations] = useState([]);
  const [messages, setMessages] = useState([]);
  const [currentConversation, setCurrentConversation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  // Récupérer le token
  const getToken = useCallback(() => {
    return localStorage.getItem('authToken');
  }, []);

  // Créer instance axios
  const createAxiosInstance = useCallback(() => {
    const instance = axios.create({
      baseURL: API_URL,
      timeout: 10000,
    });

    instance.interceptors.request.use((config) => {
      const token = getToken();
      if (token) {
        config.headers.Authorization = `Bearer ${token}`;
      }
      return config;
    });

    return instance;
  }, [getToken]);

  // Récupérer les messages d'une conversation
  const fetchMessages = useCallback(async (conversationId) => {
    try {
      setLoading(true);
      setError(null);
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.get(`/messages/conversations/${conversationId}/messages`);

      if (response.data.success) {
        setMessages(response.data.messages || []);
        setCurrentConversation(response.data.conversation);
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur');
    } finally {
      setLoading(false);
    }
  }, [createAxiosInstance]);

  // Récupérer toutes les conversations
  const fetchConversations = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.get('/messages/conversations');

      if (response.data.success) {
        setConversations(response.data.conversations || []);
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur');
    } finally {
      setLoading(false);
    }
  }, [createAxiosInstance]);

  // Créer ou récupérer une conversation
  const getOrCreateConversation = useCallback(async (adminId) => {
    try {
      setLoading(true);
      setError(null);
      const axiosInstance = createAxiosInstance();

      // Vérifier d'abord les conversations existantes
      if (conversations.length > 0) {
        const existing = conversations.find(c => c.admin_id === adminId);
        if (existing) {
          await fetchMessages(existing.id);
          return existing;
        }
      }

      // Créer une nouvelle
      const response = await axiosInstance.post('/messages/conversations', {
        admin_id: adminId
      });

      if (response.data.success) {
        const newConv = response.data.conversation;
        setConversations(prev => [newConv, ...prev]);
        setCurrentConversation(newConv);
        return newConv;
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur');
    } finally {
      setLoading(false);
    }
  }, [conversations, createAxiosInstance, fetchMessages]);

  // Envoyer un message
  const sendMessage = useCallback(async (conversationId, content) => {
    try {
      const axiosInstance = createAxiosInstance();

      const response = await axiosInstance.post('/messages/messages', {
        conversation_id: conversationId,
        content: content.trim()
      });

      if (response.data.success) {
        const newMessage = response.data.message;
        setMessages(prev => [...prev, newMessage]);
        return newMessage;
      }
    } catch (err) {
      setError(err.response?.data?.message || 'Erreur');
      throw err;
    }
  }, [createAxiosInstance]);

  // Récupérer les admins
  const fetchAdmins = useCallback(async () => {
    try {
      const axiosInstance = createAxiosInstance();
      const response = await axiosInstance.get('/users/admins');
      return response.data.success ? response.data.admins : [];
    } catch (err) {
      return [];
    }
  }, [createAxiosInstance]);

  // Initialisation
  useEffect(() => {
    if (getToken()) {
      fetchConversations();
    }
  }, [getToken, fetchConversations]);

  return {
    conversations,
    messages,
    currentConversation,
    loading,
    error,
    fetchConversations,
    getOrCreateConversation,
    fetchMessages,
    sendMessage,
    fetchAdmins
  };
};

export default useMessages;
